import { getRecordingTranscriptMockResponse } from "@api/mock/state/recordingSpeaker";
import { http, HttpResponse } from "msw";

// 경로 파라미터가 있어 fetch 상수 대신 패턴을 직접 적어요
export const recordingTranscriptHandlers = [
  http.get(
    "*/api/v1/workspaces/:workspaceId/recordings/:recordingId/transcript",
    ({ params }) =>
      HttpResponse.json(
        getRecordingTranscriptMockResponse(
          Number(params.workspaceId),
          Number(params.recordingId),
        ),
      ),
  ),
];
